import std.io
import std.collections

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let m = collections.mapOf([10, 20, 30], [1, 2, 3])
    let ks = m.keys()
    for k in ks {
        match m.get(k) {
            Some(v) => { io.println("${k}=${v}") }
            None => { io.println("miss") }
        }
    }
    return Ok(())
}
